function clearPricePending(p:any){if(busy.value||!samePricePending(pending.value,p))return;pricePendingTarget(p);pending.value={...p,phase:p.phase==='rejected'?'rejected':'confirmed',known:true};const key='adc.clinicalPending:'+props.staff.accountId;try{try{keepPriceCache(sessionStorage,key,pending.value,props.staff);}catch{}clearPriceCache(sessionStorage,key,pending.value,props.staff);pending.value=null;mode.value='';notice.value='原调价保存已核实；本次仅清理提示。';void refresh(true);}catch(e){error.value=explain(e);}}
async function sendPrice(path:string,body:any,label:string){if(busy.value)return;if(cacheBlocked.value){error.value=cacheError.value;return;}if(pending.value?.known){error.value='原调价已知成功，只需清理提示。';return;}if(pending.value&&!samePricePending(pending.value,{path,body})){error.value='请先核实原调价请求。';return;}const wasPending=!!pending.value,owner={accountId:props.staff.accountId,employeeId:props.staff.employeeId},key='adc.clinicalPending:'+owner.accountId,p={path,body,label}as any,own=saveGuard(p,samePricePending);let sent=false;busy.value=true;error.value='';notice.value='';try{Object.assign(p,priceCommand(p,owner));keepPriceCache(sessionStorage,key,p,owner);pending.value=p;sent=true;const r=await api(path,p.body);if(!own())return;validPriceSaved(p,r);pending.value={...p,phase:'confirmed',known:true};mode.value='';notice.value='参考价新版本已保存；旧账单采用价不回算。';try{try{keepPriceCache(sessionStorage,key,pending.value,owner);}catch{}clearPriceCache(sessionStorage,key,pending.value,owner);pending.value=null;}catch(e){error.value=explain(e);}busy.value=false;try{await refresh(true);}catch(e){if(own.active())error.value='调价已保存，重新读取失败；请稍后刷新。';}return r;}catch(e){if(!(sent?own():own.active()))return;error.value=explain(e);if(sent&&!wasPending&&e instanceof ApiError&&e.status>=400&&e.status<500&&e.status!==401){pending.value={...p,known:true,phase:'rejected'};try{try{keepPriceCache(sessionStorage,key,pending.value,owner);}catch{}clearPriceCache(sessionStorage,key,pending.value,owner);pending.value=null;}catch{}if(pending.value?.known)mode.value='';return;}if(sent){mode.value='';pending.value=p;error.value='原调价结果待核实，请先只读查询；已保留原请求。';if(e instanceof ApiError&&e.status===401)emit('unauthorized');}}finally{if(own.active())busy.value=false;}}
async function send(path:string,body:any,label:string){if(cacheBlocked.value){error.value=cacheError.value;return;}if(isPricePending({path}))return sendPrice(path,body,label);if(isRecordPending({path}))return sendRecord(path,body,label);if(isBillPending({path}))return sendBill(path,body,label);if(isClinicalReceiptPending({path}))return sendReceipt(path,body,label);error.value='未识别的诊疗提交路径，未发送。';}

async function save(){const f=form.value,d=detail.value,requestId=crypto.randomUUID();try{
 if(mode.value==='record')return send(`/visits/${d.visit.id}/record`,{requestId,recordVersion:d.record?.version||0,body:f.body||null,pendingNote:f.pendingNote||null,completeness:f.completeness,clinicalAt:instant(f.clinicalAt),doctorConfirmed:f.doctorConfirmed,reason:f.reason||null,treatments:f.treatments.map((t:any)=>({id:t.id||null,version:t.version||0,itemId:t.itemId,performedAt:instant(t.performedAt),teeth:t.teethText.split(/[、,，\s]+/).map((x:string)=>x.trim()).filter(Boolean)}))},'病历状态和医生确认治疗已保存。');
 if(mode.value==='bill'){if(!currentDraft.value){error.value='请按当前明细重新计算并核对草稿。';return;}return send(`/visits/${d.visit.id}/bill`,{...billingBody(),requestId,draftToken:draft.value.draftToken,reason:f.reason||null},f.billId?'待付款账单更正已保存并留原版。':'正式账单已生成，当前为待付款。');}
 if(mode.value==='receipt')return send(`/visits/${d.visit.id}/receipt`,{requestId,billVersion:d.bill.version,amount:f.amount,paymentMethod:f.paymentMethod,receivedAt:instant(f.receivedAt),actualReceived:f.actualReceived,basis:f.basis,adjustmentIds:f.adjustmentIds},'已登记真实全额实收，账单显示已付款。');
 if(mode.value==='price')return send('/prices',{requestId,clinicId:clinic.value,itemId:f.itemId,amount:f.amount,effectiveFrom:instant(f.effectiveFrom),reason:f.reason},'参考价新版本已保存；旧账单采用价不回算。');
}catch(e){error.value=explain(e);}}

function openFollowup(t:any){if(!detail.value||busy.value||loading.value||mode.value||pending.value||cacheBlocked.value||props.sourceEntry||sourceActive.value||detail.value.visit.clinicId!==clinic.value||!['followup.read','followup.manage'].every(f=>props.staff.functions?.includes(f))||!detail.value.treatments.includes(t))return;emit('open-followup',treatmentEntry({accountId:props.staff.accountId,employeeId:props.staff.employeeId,clinicId:clinic.value,date:date.value,visitId:detail.value.visit.id,treatmentId:t.id,treatmentVersion:t.version},props.staff));}
function openCare(){if(!detail.value||busy.value||loading.value||mode.value||pending.value||cacheBlocked.value||props.sourceEntry||sourceActive.value||!props.staff.functions?.some((f:string)=>['image.read','lab.read'].includes(f))||detail.value.visit.clinicId!==clinic.value)return;emit('open-care',visitEntry({accountId:props.staff.accountId,employeeId:props.staff.employeeId,clinicId:clinic.value,date:date.value,visitId:detail.value.visit.id},props.staff));}
async function openHandoff(){if(!props.visitEntry||busy.value||(loading.value&&!initialized.value)||mode.value||pending.value||cacheBlocked.value)return;const e=visitEntry(props.visitEntry,props.staff);if(clinic.value!==e.clinicId||date.value!==e.date){error.value='交接范围已改变，请返回原诊所和日期后重读。';return;}const current=pageScope.capture(),expected=detailGeneration+1;await select(e.visitId);if(!current()||detailGeneration!==expected)return;if(detail.value&&(detail.value.visit.id!==e.visitId||detail.value.visit.clinicId!==e.clinicId)){clearPrivate();error.value='交接就诊与当前诊所不一致，未显示内容。';}}

onMounted(initialize);defineExpose({refresh});
</script>

<template><div v-if="props.visitEntry" class="b-card"><p>已返回原诊疗就诊；按当前权限重新读取。</p><button class="b-button outline small" :disabled="busy||loading||!!mode||!!pending||cacheBlocked" @click="openHandoff">重读交接就诊</button></div><div class="clinical-workspace"><section v-if="cacheBlocked||cacheError" class="b-alert warning"><p>{{cacheError}}</p><button class="b-button outline" :disabled="busy" @click="restoreCache">重新读取原缓存</button></section>
 <div v-if="error" class="b-alert error" role="alert">{{error}}<button @click="error=''">关闭</button></div><div v-if="queueError" class="b-alert error" role="alert">{{queueError}}</div><div v-if="notice" class="b-alert success" role="status"><Check :size="17"/>{{notice}}<button @click="notice=''">关闭</button></div><ClinicalPriceRecovery v-if="pending&&isPricePending(pending)" :staff="staff" :pending="pending" :busy="busy" @clear="clearPricePending" @retry="send($event.path,$event.body,$event.label)"/><ClinicalReceiptRecovery v-else-if="pending&&isClinicalReceiptPending(pending)" :staff="staff" :pending="pending" :busy="busy" @clear="clearReceiptPending" @retry="send($event.path,$event.body,$event.label)"/><ClinicalBillRecovery v-else-if="pending&&isBillPending(pending)" :staff="staff" :pending="pending" :busy="busy" @clear="clearBillPending" @retry="send($event.path,$event.body,$event.label)"/><ClinicalRecordRecovery v-else-if="pending&&isRecordPending(pending)" :staff="staff" :pending="pending" :busy="busy" @clear="clearRecordPending" @retry="send($event.path,$event.body,$event.label)"/><div v-else-if="pending" class="b-alert warning">存在待核实原提交。<button class="b-button small" :disabled="busy" @click="send(pending.path,pending.body,pending.label)">核实原提交</button></div>
 <div class="f-tabs"><button :class="{active:section==='visits'}" @click="section='visits'"><Stethoscope :size="17"/>诊疗与收费</button><button v-if="canSeePrices" :class="{active:section==='prices'}" :disabled="busy||!!pending||!!mode" @click="sourceChanged();section='prices';detail=null"><ReceiptText :size="17"/>参考价目</button></div>
 <div class="b-card f-toolbar c-scope"><label>诊所<select v-model="clinic" :disabled="busy||loading||!!pending||!!mode" @change="refresh()"><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>实际到院日期<input type="date" v-model="date" :disabled="busy||loading||!!pending||!!mode" @change="refresh()"/></label><button class="b-button outline small" :disabled="loading||queueLoading||busy||!!pending" @click="refresh()"><RefreshCw :size="15"/>刷新</button></div>
 <div v-if="!initialized" class="b-card b-empty">{{loading?'正在连接…':'未取得工作范围'}}<button :disabled="loading" class="b-button outline" @click="initialize">重新连接</button></div><div v-else-if="!clinics.length" class="b-card b-empty">当前账号没有诊疗或收费范围。</div>
 <div v-else-if="section==='prices'&&!canSeePrices" class="b-card b-empty">当前诊所没有参考价查看权限。</div><template v-else-if="section==='prices'"><section class="b-card f-list"><div class="f-list-head"><div><h2>已有治疗项目参考价</h2><p>新版本按诊所和生效区间保存，账单采用的价格不会回算。</p></div></div><div class="b-table-scroll"><table><thead><tr><th>项目 / 计费单位</th><th>当前参考单价</th><th>版本</th><th>维护</th></tr></thead><tbody><tr v-for="i in items" :key="i.id"><td>{{i.name}}<small>{{i.unit}}</small></td><td>{{i.referencePrice??'未配置'}}</td><td>{{i.priceVersion||'—'}}</td><td><button v-if="canPrice" class="b-button outline small" :disabled="busy||!!pending" @click="open('price',i)">新增价格版本</button></td></tr></tbody></table></div></section></template>
 <template v-else>
 <ClinicalRecordSourcePanel v-if="capability.clinicalRead" ref="recordSourceRef" :staff="staff" :clinic-id="clinic" :date="date" :entry="sourceEntry" :blocked="busy||loading||!!pending||!!mode" @selected="selectSource" @context-change="sourceChanged" @unauthorized="historyUnauthorized(401)" @access-lost="historyUnauthorized(403)" @return-quality="returnQuality"/>
 <button v-else-if="sourceEntry" class="b-button outline" :disabled="busy||loading||!!pending||!!mode" @click="returnQuality">返回原资料问题</button>
 <section v-if="!detail" class="c-queue">
 <form class="b-card c-queue-filters" @submit.prevent="queryVisits">
  <label>患者姓名<input v-model="search" placeholder="按姓名检索" maxlength="100" :disabled="busy||!!pending"/></label>
  <label>接诊医生<select v-model="doctorId" :disabled="busy||!!pending"><option value="">全部授权医生</option><option v-for="d in doctors" :key="d.id" :value="d.id">{{d.name}}</option></select></label>
  <label>接诊进展<select v-model="progress" :disabled="busy||!!pending"><option value="all">全部进展</option><option v-for="(label,key) in progressLabels" :value="key" :key="key">{{label}}</option></select></label>
  <label v-if="capability.clinicalRead">病历状态<select v-model="recordFilter" :disabled="busy||!!pending"><option value="all">全部病历状态</option><option v-for="(label,key) in recordLabels" :key="key" :value="key">{{label}}</option></select></label>
  <label v-if="capability.billRead">账单状态<select v-model="paymentFilter" :disabled="busy||!!pending"><option value="all">全部账单状态</option><option v-for="(label,key) in status" :key="key" :value="key">{{label}}</option></select></label>
  <label>每页就诊<select v-model="pageSize" :disabled="busy||!!pending"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select></label>
  <div class="c-queue-actions"><button class="b-button" :disabled="loading||queueLoading||busy||!!pending">查询就诊</button><button class="b-button outline" type="button" :disabled="loading||queueLoading||busy||!!pending" @click="clearFilters">清空筛选</button></div>
  <p class="c-queue-note" v-if="queueDirty">筛选条件已改变，请查询后查看新结果。</p>
  <p class="c-queue-note" v-if="asOf">已显示 {{rows.length}} / {{matched}} 次 · 读取时点 {{full(asOf)}}。统计覆盖当前日期、姓名和医生范围，不随下方三类状态筛选或分页缩小。</p>
 </form>
 <div class="c-queue-overview"><section v-for="card in overview" :key="card.label" class="b-card"><strong>{{queueLoading?'—':card.n??'—'}}</strong><span>{{card.label}}</span></section></div>
 <p v-if="summary" class="c-queue-note">接诊进展：候诊 {{summary.progress.waiting}} · 接诊中 {{summary.progress.in_progress}} · 已结束 {{summary.progress.ended}} · 已离开 {{summary.progress.left}}。<template v-if="capability.clinicalRead">病历统计仅含本人负责或参与的 {{summary.record.available}} 次。</template><template v-if="capability.clinicalRead&&capability.billRead">账单供阅 {{summary.payment.available}} 次：未开单 {{summary.payment.not_billed}} · 待付款 {{summary.payment.unpaid}} · 已付款 {{summary.payment.paid}}。</template>接诊、病历、账单为独立维度，付款和离开均不推定病历完整或治疗完成。</p>
 <section class="b-card f-list c-queue-list"><div class="f-list-head"><div><h2>{{capability.settlement?'治疗账单与结算':'本人参与的实际就诊'}}</h2><p>{{capability.settlement?'按本店结算职责供阅，病历仅供负责或参与的医护。':'选择前台已登记的实际就诊，按当前岗位处理。'}}</p></div></div>
 <div class="b-table-scroll"><table><thead><tr><th>患者 / 实际到院</th><th>接诊医生</th><th>接诊进展</th><th v-if="capability.clinicalRead">病历与治疗</th><th v-if="capability.billRead">账单</th><th>操作</th></tr></thead><tbody>
 <tr v-for="v in rows" :key="v.id"><td><strong>{{v.patientName}}</strong><small>{{full(v.arrivedAt)}}</small><small>就诊 {{v.id.slice(0,8).toUpperCase()}}</small></td><td>{{v.doctorName}}</td><td>{{progressLabels[v.progress]}}</td><td v-if="capability.clinicalRead">{{recordLabels[v.recordState]||'—'}}<small v-if="v.canClinical">医生确认 {{v.treatmentCount}} 项</small></td><td v-if="capability.billRead"><span class="b-pill" :class="v.paymentState==='paid'?'active':''">{{status[v.paymentState]||'—'}}</span></td><td><button class="b-button outline small" :disabled="busy||queueLoading||queueDirty||!!pending" @click="select(v.id)">{{v.canCollect?'核对结算':'打开就诊'}}</button></td></tr>
 <tr v-if="!rows.length"><td colspan="6" class="b-empty">{{queueLoading?'正在读取就诊…':asOf?'当前条件下没有授权就诊。':'请选择日期并查询授权就诊。'}}</td></tr></tbody></table></div>
 <div v-if="nextCursor" class="c-queue-more"><button class="b-button outline" :disabled="queueLoading||queueDirty||busy||!!pending" @click="queue.load(true)">{{queueLoading?'正在读取…':'继续读取就诊'}}</button></div>
 </section></section>
 <template v-else><button class="c-back" :disabled="busy||!!pending||!!mode" @click="sourceActive=false;detail=null"><ArrowLeft :size="16"/>返回就诊列表</button><section class="b-card c-patient"><div><h2>{{detail.visit.patientName}}</h2><button v-if="!props.sourceEntry&&!sourceActive&&props.staff.functions?.some((f:string)=>['image.read','lab.read'].includes(f))" class="b-button outline small" :disabled="busy||loading||!!mode||!!pending||cacheBlocked" @click="openCare">查看本次影像与加工</button><p>{{detail.visit.doctorName}} · 到院 {{full(detail.visit.arrivedAt)}} <span v-if="detail.visit.leftAt">· 已离开 {{full(detail.visit.leftAt)}}</span></p></div><div v-if="detail.canClinical" class="c-allergy">当前档案过敏了解状态：{{{unknown:'尚未了解',none_reported:'患者表示无已知过敏',reported:'已报告过敏'}[detail.allergy?.knowledge]||'尚未了解'}}<small v-if="detail.allergy?.asOf">读取时点：{{full(detail.allergy.asOf)}}</small><small v-if="detail.allergy?.note">{{detail.allergy.note}}</small><small v-for="item in detail.allergy?.items||[]" :key="item.id">{{item.allergen}}<span v-if="item.description">：{{item.description}}</span></small><small v-if="detail.allergy?.tags?.length">标签：{{detail.allergy.tags.join('、')}}</small><small v-if="detail.allergy?.knowledge==='reported'&&!detail.allergy?.itemsAccessible">详细条目须具备患者健康资料查询权限。</small></div></section>
 <section v-if="detail.canClinical" class="b-card c-block"><div class="f-list-head"><div><h2>诊疗记录与医生确认项目</h2><p>病历完整性与开费、实收分别表达。</p></div><button v-if="canWrite" class="b-button small" :disabled="busy||!!pending" @click="open('record')">{{detail.record?'更正诊疗记录':'记录并确认治疗'}}</button></div><div class="c-record"><span class="b-pill">{{detail.record?detail.record.completeness==='pending'?'病历待补':'病历完整':'尚无病历'}}</span><p v-if="detail.record?.body" class="c-body-text">{{detail.record.body}}</p><p v-if="detail.record?.pendingNote" class="c-pending">待补说明：{{detail.record.pendingNote}}</p><div v-for="t in detail.treatments" :key="t.id" class="c-treatment"><strong>{{t.name}}</strong><span>牙位：{{t.teeth.join('、')||'无特定牙位'}}</span><small>实施 {{full(t.performedAt)}} · 医生确认 {{full(t.confirmedAt)}} · 版本 {{t.version}}</small><button v-if="!props.sourceEntry&&!sourceActive&&['followup.read','followup.manage'].every(f=>props.staff.functions?.includes(f))" type="button" class="b-button outline small" :disabled="busy||loading||!!mode||!!pending||cacheBlocked" @click="openFollowup(t)">基于此治疗安排随访</button></div><p v-if="!detail.treatments.length" class="b-help">尚无医生确认的实际治疗，不自动生成费用。</p></div></section>
 <section v-if="detail.canBill" class="b-card c-block"><div class="f-list-head"><div><h2>治疗账单</h2><p>数量经录入核对后才计算草稿，正式账单确认后保存。</p></div><button v-if="canBill&&detail.bill?.paymentState!=='paid'" class="b-button small" :disabled="busy||!!pending" @click="open('bill')">{{detail.bill?'核对 / 更正待付账单':'填写明细并核费'}}</button></div><div v-if="!detail.bill" class="b-empty">当前尚无正式治疗账单</div><template v-else><div class="b-table-scroll"><table><thead><tr><th>采用项目 / 牙位</th><th>数量 / 单位</th><th>采用单价</th><th>小计</th></tr></thead><tbody><tr v-for="l in detail.bill.lines" :key="l.id"><td>{{l.name}}<small>{{l.teeth.join('、')||'无特定牙位'}}</small></td><td>{{l.quantity}} {{l.unit}}</td><td>¥{{l.unitPrice}}</td><td>¥{{l.subtotal}}</td></tr></tbody></table></div><div class="c-total"><span class="b-pill" :class="detail.bill.paymentState==='paid'?'active':''">{{status[detail.bill.paymentState]}}</span><small>账单 {{detail.bill.id.slice(0,8).toUpperCase()}} · 版本 {{detail.bill.version}}</small><strong>合计 ¥{{detail.bill.total}}</strong><button v-if="canCollect&&detail.bill.paymentState==='unpaid'" class="b-button" :disabled="busy||!!pending" @click="open('receipt')">登记真实收款</button></div><div v-if="detail.bill.receipt" class="c-receipt"><Check :size="19"/><div><strong>实收 ¥{{detail.bill.receipt.amount}} · {{methods[detail.bill.receipt.paymentMethod]}}</strong><p>实际到账 {{full(detail.bill.receipt.receivedAt)}} · 首次登记 {{full(detail.bill.receipt.registeredAt)}}</p><small>核实依据：{{detail.bill.receipt.basis}}</small></div></div></template></section>
 <ClinicalHistoryPanel :key="detail.visit.id" :visit-id="detail.visit.id" :can-clinical="detail.canClinical" :can-bill="detail.canBill" :treatments="detail.treatments" @unauthorized="historyUnauthorized"/>
 </template></template>
 <div v-if="mode" class="b-backdrop"><form class="b-dialog c-dialog" role="dialog" aria-modal="true" @submit.prevent="save"><button class="b-close" type="button" aria-label="关闭诊疗收费办理" :disabled="busy||!!pending" @click="close"><X :size="21"/></button><div class="b-eyebrow">CLINICAL CARE / BILLING</div><h2>{{{record:'医生记录并确认实际治疗',bill:'逐项核对治疗费用',receipt:'前台登记真实全额实收',price:'新增项目价格版本'}[mode]}}</h2><div v-if="detail" class="f-context">{{detail.visit.patientName}} · {{detail.visit.doctorName}}</div><div v-if="error" class="b-alert error" role="alert">{{error}}</div>
 <template v-if="mode==='record'"><div class="b-two-fields"><label>实际诊疗时间（北京时间）<input :disabled="!!pending" type="datetime-local" step="1" v-model="form.clinicalAt" required/></label><label>正文状态<select :disabled="!!pending" v-model="form.completeness"><option value="pending">正文待补</option><option value="complete">正文完整</option></select></label></div><label>病历正文<textarea :disabled="!!pending" v-model="form.body" :required="form.completeness==='complete'" rows="3" maxlength="10000"/></label><label>待补说明<textarea :disabled="!!pending" v-model="form.pendingNote" :required="form.completeness==='pending'" rows="2" maxlength="1000"/></label><div class="c-subheading"><strong>实际完成的治疗</strong><button type="button" class="b-button outline small" :disabled="!!pending" @click="form.treatments.push(newTreatment())"><Plus :size="15"/>增加一项</button></div><div v-for="(t,i) in form.treatments" :key="t.id||i" class="c-treatment-edit"><label>实际项目<select :disabled="!!pending" v-model="t.itemId" required><option value="">请医生明确选择</option><option v-for="item in items" :key="item.id" :value="item.id">{{item.name}}</option></select></label><div class="b-two-fields"><label>适用牙位（可多项或留空）<input :disabled="!!pending" v-model="t.teethText" placeholder="例如16、17；无特定牙位留空"/></label><label>实际实施时间<input :disabled="!!pending" type="datetime-local" step="1" v-model="t.performedAt" required/></label></div><button v-if="!t.id" class="f-text" type="button" :disabled="!!pending" @click="form.treatments.splice(i,1)">移除未保存条目</button></div><label v-if="detail.record">更正原因<input :disabled="!!pending" v-model="form.reason" required maxlength="1000"/></label><label class="b-checkbox"><input :disabled="!!pending" type="checkbox" v-model="form.doctorConfirmed" required/><span>医生已核对实际项目、适用牙位及时刻，明确确认上述治疗；不由护士代作临床决定。</span></label></template>
 <template v-if="mode==='bill'"><p class="b-help">计费数量请逐项填写，不由项目或牙位猜为1。参考价仅供核对；没有有效参考价须先维护。</p><div v-for="l in form.lines" :key="l.treatmentId" class="c-treatment-edit"><strong>{{l.name}}</strong><p class="b-help">牙位 {{l.teeth.join('、')||'无特定牙位'}} · 单位 {{l.unit}} · 参考价 {{l.referencePrice??'未配置'}}</p><div class="b-two-fields"><label>计费数量<input :disabled="!!pending" v-model="l.quantity" inputmode="decimal" required placeholder="请明确录入数量"/></label><label>核对后的采用单价<input :disabled="!!pending" v-model="l.unitPrice" inputmode="decimal" required/></label></div></div><label>采用价与参考价不同时的核对依据<input :disabled="!!pending" v-model="form.priceBasis" maxlength="1000"/></label><label v-if="form.billId">待付款账单更正原因<input :disabled="!!pending" v-model="form.reason" required maxlength="1000"/></label><button type="button" class="b-button outline full" :disabled="busy" @click="calculate">计算费用草稿</button><div v-if="currentDraft" class="c-draft"><p v-for="l in draft.lines" :key="l.treatmentId">{{l.name}}<strong>¥{{l.subtotal}}</strong></p><div>草稿合计<strong>¥{{draft.total}}</strong></div><small>核对确认前，不生成正式账单或收入。</small></div><p v-else-if="draft" class="b-help">明细已变化，请重新计算。</p><label class="b-checkbox"><input :disabled="!!pending" type="checkbox" v-model="form.checked" required/><span>已核对逐项数量、单价、小计及合计，确认开单。</span></label></template>
 <template v-if="mode==='receipt'"><div class="c-pay-due">应收全额<strong>¥{{detail.bill.total}}</strong></div><div class="b-two-fields"><label>已核实的实收金额<input :disabled="!!pending" v-model="form.amount" inputmode="decimal" required placeholder="请录入实际全额"/></label><label>实际付款方式<select :disabled="!!pending" v-model="form.paymentMethod" required><option value="">请选择实际方式</option><option v-for="(label,key) in methods" :key="key" :value="key">{{label}}</option></select></label></div><label>经核实的实际到账时间（北京时间）<input :disabled="!!pending" type="datetime-local" step="1" v-model="form.receivedAt" required/></label><label>真实收款核实依据 / 补录原因<textarea :disabled="!!pending" v-model="form.basis" required rows="2"/></label><ReceiptAdjustmentPicker v-model="form.adjustmentIds" :clinic-id="clinic" kind="bill" :received-at="instant(form.receivedAt)" :disabled="busy||!!pending"/><label class="b-checkbox"><input :disabled="!!pending" type="checkbox" v-model="form.actualReceived" required/><span>前台已核实实际收到全额付款。这里只登记已发生事实，不执行扣款。</span></label></template>
 <template v-if="mode==='price'"><div class="f-context">{{form.name}}</div><label>新参考价<input :disabled="!!pending" v-model="form.amount" inputmode="decimal" required/></label><label>生效时间（北京时间）<input :disabled="!!pending" type="datetime-local" step="1" v-model="form.effectiveFrom" required/></label><label>维护依据<textarea :disabled="!!pending" v-model="form.reason" required rows="2"/></label><p class="b-help">仅本诊所已有项目。当前或未来生效，不回算旧账单；跨店共享版不能只截断一店。</p></template>
 <button v-if="pending" class="b-button full" type="button" :disabled="busy" @click="send(pending.path,pending.body,pending.label)">核实原提交</button><button v-else class="b-button full" :disabled="busy||(mode==='bill'&&!currentDraft)">{{busy?'正在保存…':mode==='record'?'确认保存诊疗':mode==='bill'?'确认正式开单':mode==='receipt'?'确认登记已收到的全额':'确认保存新价格'}}</button><p class="b-help">请核对当前患者、就诊和本次办理内容；仅保存已核实的实际记录。</p>
 </form></div>
</div></template>

